@extends('store.layout')
@section('title','El Dorado - Trabaja con nosotros')
@section('content')
<style>.jobs-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}.job-card{padding:20px;border:1px solid #efb98d;border-radius:18px;background:#fff8f1;color:#25170f}.job-card h2{color:#25170f!important}.job-card p{color:#68432e}.job-card button{width:100%}</style>
<section class="panel"><p class="eyebrow">Oportunidades</p><h1 class="title">Trabaja con nosotros</h1><p class="muted-main">Revisa las vacantes publicadas por el administrador y postula directamente por WhatsApp.</p><div id="jobsList" class="jobs-grid">Cargando vacantes...</div></section>
@endsection
@section('scripts')<script>(()=>{const list=document.getElementById('jobsList');let phone='';Promise.all([fetch('/api/v1/jobs').then(r=>r.json()),fetch('/api/v1/settings/public').then(r=>r.json())]).then(([jobs,settings])=>{phone=String(settings.support_phone||'').replace(/\D/g,'');list.innerHTML=Array.isArray(jobs)&&jobs.length?jobs.map(j=>`<article class="job-card"><h2>${String(j.title).replace(/[<>&]/g,'')}</h2><p>${String(j.description||'Comunícate con nosotros para conocer los requisitos.').replace(/[<>&]/g,'')}</p><button class="btn-main" data-job="${j.id}" data-title="${String(j.title).replace(/"/g,'')}">Postula</button></article>`).join(''):'<article class="job-card"><h2>Sin vacantes disponibles</h2><p>Vuelve pronto para revisar nuevas oportunidades.</p></article>';list.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>window.open(`https://wa.me/${phone}?text=${encodeURIComponent(`Hola, deseo postular al puesto: ${b.dataset.title}`)}`,'_blank','noopener'))}).catch(()=>list.textContent='No se pudieron cargar las vacantes.')})();</script>@endsection
